ls in domain, communications, or work context"},{"id":"org-key-contact-inferred","field":"key_contact","when":{"signal":"org_has_primary_contact","op":"eq","value":true},"set":{"value":"{{inferred_key_contact}}"},"confidence":82,"because":"The linked person is the clearest primary contact for this organization"}]}'::jsonb,
